            <div x-show="hasVariants"><h3 class="font-semibold">Biến thể và tồn đầu kỳ</h3><ul class="mt-2 divide-y divide-slate-100 rounded-xl border border-slate-200"><template x-for="(row,index) in variants" :key="index"><li class="flex flex-wrap justify-between gap-2 p-3 text-sm"><span x-text="row.variant_name || 'Chưa đặt tên'"></span><span class="font-mono" x-text="dirty ? 'Lưu để cập nhật SKU' : (row.sku || 'Chưa có SKU')"></span><span x-text="'Tồn: '+(row.initial_stock || '0')"></span><span x-text="'Retail: '+(row.retail_price_override || 'giá mặc định')"></span></li></template></ul></div>
            <div x-show="!hasVariants" class="text-sm">Một SKU · Tồn đầu kỳ: {{ $data['initial_stock'] ?? '0' }} · Giá Retail: {{ $data['retail_price'] ?? '—' }}</div><div x-show="sellableDealer"><h3 class="font-semibold">Giá Dealer / MOQ</h3><ul class="mt-2 list-inside list-disc text-sm"><template x-for="(rule,index) in dealerRules" :key="index"><li x-text="'Tier '+rule.tier_id+' · SKU '+(hasVariants ? (variants[rule.variant_index]?.variant_name || 'chưa chọn') : baseSku)+' · MOQ '+rule.min_quantity+' · Giá '+rule.unit_price"></li></template></ul></div>
